#include <Wire.h>
#include <BH1750.h>
#include <Servo.h>

// HC-SR04
const byte TRIG_PIN = 7;
const byte ECHO_PIN = 6;

// Сервопривод
const byte SERVO_PIN = 9;

// Порог расстояния
const float DISTANCE_LIMIT = 20.0;  // см

// Порог яркого освещения
const float LIGHT_LIMIT = 500.0;    // люкс

// Положения сервопривода
const int HOME_POSITION = 0;
const int ACTIVE_POSITION = 90;

BH1750 lightSensor;
Servo servo;

float getDistance() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);

  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000);

  // Если эхо не получено
  if (duration == 0) {
    return -1;
  }

  // Расчёт расстояния в сантиметрах
  return duration * 0.0343 / 2.0;
}

void setup() {
  Serial.begin(9600);

  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

  servo.attach(SERVO_PIN);
  servo.write(HOME_POSITION);

  Wire.begin();

  if (!lightSensor.begin()) {
    Serial.println("BH1750 не найден!");
    while (true);
  }

  Serial.println("Система запущена");
}

void loop() {
  float distance = getDistance();
  float illumination = lightSensor.readLightLevel();

  Serial.print("Расстояние: ");
  Serial.print(distance);
  Serial.print(" см | Освещённость: ");
  Serial.print(illumination);
  Serial.println(" лк");

  // Яркое освещение имеет приоритет
  if (illumination >= LIGHT_LIMIT) {
    servo.write(HOME_POSITION);
    Serial.println("Яркий свет: исходное положение");
  }
  else if (distance > 0 && distance <= DISTANCE_LIMIT) {
    servo.write(ACTIVE_POSITION);
    Serial.println("Объект близко: активное положение");
  }
  else {
    servo.write(HOME_POSITION);
  }

  delay(300);
}
